import React from 'react';
import CustomNav from '../CustomsNav';
import { userData } from '../../helpers';
import { useProducts } from './useProduct';

const Home = () => {
    const { username } = userData();
    const { categories, products } = useProducts();

    console.log({ categories });
    console.log({ products });

    return (
        <div>
            <CustomNav />
            <div className='Home'>
                <h2 style={{ textAlign: "center" }}>Enjoy our sales!</h2>

                {/* Check if categories and products are available */}
                {categories && products && categories.length > 0 && products.length > 0 ? (
                    categories.map((category) => {
                        // Filter products that belong to this category
                        const filteredProducts = products.filter((product) => {
                            // Safely check if category exists for each product
                            return (
                                product.attributes &&
                                product.attributes.category &&
                                product.attributes.category.data &&
                                product.attributes.category.data.id === category.id
                            );
                        });

                        // Render category and its products if filteredProducts is not empty
                        if (filteredProducts.length > 0) {
                            return (
                                <div key={category.id}>
                                    <h3>{category.name}</h3>
                                    {filteredProducts.map((product) => (
                                        <div key={product.id}>
                                            <h4>{product.attributes.name}</h4>
                                            <p>{product.attributes.description || "No description available"}</p>
                                        </div>
                                    ))}
                                </div>
                            );
                        }
                        return null;
                    })
                ) : (
                    <p>Loading...</p> // Render loading message if categories or products are not loaded
                )}
            </div>
        </div>
    );
}

export default Home;
